// ═══ FUTURE (Java 5) — limited ═══
ExecutorService pool = Executors.newFixedThreadPool(4);
Future<String> future = pool.submit(() -> settleTrade("TRD-001"));

// ONLY operations:
future.get();                        // BLOCKS until done!
future.get(5, TimeUnit.SECONDS);    // blocks with timeout
future.isDone();                     // poll: done yet?
future.cancel(true);                 // attempt cancel
future.isCancelled();

// CAN'T DO:
// future.thenApply(...)       → NO chaining!
// future.thenCombine(other)   → NO composition!
// future.exceptionally(...)    → NO error callbacks!
// future.complete("manual")   → NO manual completion!
// Only option: poll isDone() in a loop or block with get()!

// ═══ COMPLETABLEFUTURE (Java 8) — everything! ═══
CompletableFuture<String> cf = CompletableFuture
    .supplyAsync(() -> settleTrade("TRD-001"))
    .thenApply(result -> "Confirmed: " + result)     // chain transform!
    .thenCombine(fetchTaxAsync(), (r, tax) -> r + ", tax: " + tax)  // combine!
    .exceptionally(ex -> "Failed: " + ex.getMessage()) // error callback!
    .whenComplete((r, ex) -> log(r, ex));              // observe!

// Non-blocking: caller is NOT blocked. Callbacks execute when ready.
// Manual completion:
CompletableFuture<String> manual = new CompletableFuture<>();
manual.complete("Manually set!");    // complete from outside!
manual.completeExceptionally(new RuntimeException("Forced error"));

// ═══ COMPARISON TABLE ═══
// Feature              Future (Java 5)        CompletableFuture (Java 8)
// Get result           get() BLOCKING         get()/join() + non-blocking callbacks
// Chain                NO                     thenApply, thenCompose
// Combine              NO                     thenCombine, allOf, anyOf
// Error handling       NO callbacks           exceptionally, handle, whenComplete
// Manual completion    NO                     complete(), completeExceptionally()
// Async variants       NO                     thenApplyAsync, supplyAsync
// Non-blocking         NO (must poll/block)   YES (callbacks fire automatically)
// Creation             pool.submit()          supplyAsync(), runAsync(), new CF()
