package com.bank.futurecf;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import static org.assertj.core.api.Assertions.*;

class FutureVsCFTest {

    // ═══ Future: blocking, no chaining ═══
    @Test
    void future_blockingOnly() throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(2);
        Future<String> future = pool.submit(() -> {
            Thread.sleep(100); return "SETTLED";
        });

        // Only way to get result: BLOCK!
        String result = future.get();  // blocks 100ms!
        assertThat(result).isEqualTo("SETTLED");

        // Can't chain: future.thenApply(...) → doesn't exist!
        pool.shutdown();
    }

    // ═══ CompletableFuture: non-blocking chain ═══
    @Test
    void cf_nonBlockingChain() throws Exception {
        CompletableFuture<String> cf = CompletableFuture
                .supplyAsync(() -> { sleep(100);
                return "SETTLED"; })
            .thenApply(r -> "Confirmed: " + r)
            .thenApply(String::toUpperCase);

        // Non-blocking: caller does other work here!
        // ...other work...

        String result = cf.join();  // collect when needed
        assertThat(result).isEqualTo("CONFIRMED: SETTLED");
    }

    // ═══ Future: combining two results → sequential! ═══
    @Test
    void future_combining_isSequential() throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(2);
            Future<Integer> f1 = pool.submit(() -> { sleep(200);
            return 100000; });
            Future<Integer> f2 = pool.submit(() -> { sleep(200);
            return 250000; });

        long start = System.currentTimeMillis();
        int balance1 = f1.get();  // blocks 200ms
        int balance2 = f2.get();  // already done (parallel submit) — ~0ms
        int total = balance1 + balance2;
        long elapsed = System.currentTimeMillis() - start;

        assertThat(total).isEqualTo(350000);
        // ~200ms — BUT: you're blocked the entire time!
        pool.shutdown();
    }

    // ═══ CF: combining — parallel + non-blocking ═══
    @Test
    void cf_combining_parallel() throws Exception {
        long start = System.currentTimeMillis();

        CompletableFuture<Integer> total = CompletableFuture
                .supplyAsync(() -> { sleep(200);
                return 100000; })
            .thenCombine(
                    CompletableFuture.supplyAsync(() -> { sleep(200);
                    return 250000; }),
                Integer::sum);

        // Non-blocking: can do other work here!
        int result = total.join();
        long elapsed = System.currentTimeMillis() - start;

        assertThat(result).isEqualTo(350000);
        assertThat(elapsed).isLessThan(400);  // parallel: ~200ms!
    }

    // ═══ CF: manual completion ═══
    @Test
    void cf_manualCompletion() throws Exception {
        CompletableFuture<String> cf = new CompletableFuture<>();
        assertThat(cf.isDone()).isFalse();

        cf.complete("Manually completed!");  // complete from outside!
        assertThat(cf.get()).isEqualTo("Manually completed!");
    }

    // ═══ CF: error recovery (impossible with Future) ═══
    @Test
    void cf_errorRecovery() throws Exception {
        String result = CompletableFuture
            .<String>supplyAsync(() -> { throw new RuntimeException("DB down!"); })
            .exceptionally(ex -> "Fallback: cached")
            .join();

        assertThat(result).isEqualTo("Fallback: cached");
        // With Future: try { future.get() } catch → no pipeline recovery!
    }

    void sleep(long ms) { try { Thread.sleep(ms); } catch (InterruptedException e) {} }
}
